$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!$viewer){http_response_code(401);exit('Sign in to follow Research reports.');}require_csrf();try{$op=(string)($_POST['op']??'');if($op==='subscribe'){living_research_set_subscription($pdo,$viewer,$report,true,true);$message='Following this Research report.';}elseif($op==='unsubscribe'){living_research_set_subscription($pdo,$viewer,$report,false);$message='Stopped following this Research report.';}else throw new RuntimeException('Unknown report action.');}catch(Throwable $e){$error=$e->getMessage();}}
