$currentVersion=(int)$report['version_number'];$viewVersionId=$version===$currentVersion?(int)$report['current_version_id']:(int)($row['id']??0);if($viewer&&living_research_ready($pdo)&&$viewVersionId>0)living_research_mark_read($pdo,$viewer,$report,$viewVersionId);
if($viewer){header('Cache-Control: private, no-store');header('Vary: Cookie');}
$reportTitle=(string)($snapshot['project']['title']??$report['title']);$reportDesc=public_discovery_meta_description((string)($snapshot['project']['summary']??$report['summary']??('Published Research report: '.$reportTitle)));$reportCanonical=public_discovery_absolute_url($config,'/research-report.php?id='.rawurlencode($report['public_id']).($version===$currentVersion?'':'&v='.$version));$reportPublic=$report['visibility']==='public';
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($reportTitle)?> · Research Report · Annotated</title><meta name="description" content="<?=h($reportDesc)?>"><?php if(!$reportPublic):?><meta name="robots" content="noindex,nofollow"><?php endif?><link rel="canonical" href="<?=h($reportCanonical)?>"><?php if($reportPublic):?><meta property="og:type" content="article"><meta property="og:title" content="<?=h($reportTitle)?> · Research Report · Annotated"><meta property="og:description" content="<?=h($reportDesc)?>"><meta property="og:url" content="<?=h($reportCanonical)?>"><?php endif?><link rel="stylesheet" href="/assets/css/app.css"></head><body>
<header class="topbar"><a class="brand" href="/">Annotated</a><nav><?php if($viewer):?><a href="/research-publications.php">Living Research</a><a href="/research.php">Research</a><?php endif?><a href="/research-report-export.php?id=<?=h($report['public_id'])?>&v=<?=h((string)$version)?>&format=json">JSON</a><a href="/research-report-export.php?id=<?=h($report['public_id'])?>&v=<?=h((string)$version)?>&format=html">HTML</a></nav></header>
