<?php if($topics):?><div class="publicationTopics"><?php foreach($topics as $topic):?><a class="badge" href="/research-topic.php?topic=<?=h((string)$topic['topic_slug'])?>"><?=h((string)$topic['topic_label'])?></a><?php endforeach?></div><?php endif?>
<div class="inlineActions livingReportActions">
<?php if($viewer):?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($report['public_id'])?>"><input type="hidden" name="op" value="<?=$subscription['subscribed']?'unsubscribe':'subscribe'?>"><button class="button <?=$subscription['subscribed']?'secondary':''?>"><?=$subscription['subscribed']?'Following':'Follow updates'?></button></form><?php endif?>
