<?php if($currentVersion>1):?><a class="button secondary" href="/research-report-diff.php?id=<?=h($report['public_id'])?>&from=<?=h((string)max(1,$version-1))?>&to=<?=h((string)$version)?>">Compare versions</a><?php endif?><a class="button secondary" href="/research-report-network.php?id=<?=h($report['public_id'])?>&v=<?=h((string)$version)?>">Research Network</a>
<button type="button" class="button secondary" data-copy-report-url data-url="<?=h($reportCanonical)?>">Copy link</button><span class="meta"><?=h((string)$subscriberCount)?> follower<?= $subscriberCount===1?'':'s' ?></span></div></div>
<?php if($readStatus['updated_since_read']&&!empty($readStatus['last_read_version'])):?><div class="card livingUpdateNotice"><strong>This report has changed since you last read it.</strong><p>You last read version <?=h((string)$readStatus['last_read_version'])?>. The current publication is version <?=h((string)$currentVersion)?>.</p><a href="/research-report-diff.php?id=<?=h($report['public_id'])?>&from=<?=h((string)$readStatus['last_read_version'])?>&to=<?=h((string)$currentVersion)?>">See what changed</a></div><?php endif?>
