<?php if(!empty($snapshot['entity_relations'])):?><h2>Entity Graph</h2><?php foreach($snapshot['entity_relations'] as $rel):?><article class="card"><p><strong><?=h((string)$rel['source_entity_id'])?></strong> <?=h(str_replace('_',' ',(string)$rel['relation_type']))?> <strong><?=h((string)$rel['target_entity_id'])?></strong></p></article><?php endforeach?><?php endif?>
